def count_pairs(arr, k, n):
    # Initialize a dictionary to store the frequency of each element
    freq = {}

    # Count the frequency of each element in the array
    for i in range(n):
        if arr[i] not in freq:
            freq[arr[i]] = 1
        else:
            freq[arr[i]] += 1

    # Initialize the count of pairs
    count = 0

    # Iterate through the array again
    for i in range(n):
        # Check if the complement (arr[i] + k) exists in the dictionary
        if arr[i] + k in freq:
            # If it does, add the minimum of the frequencies of arr[i] and arr[i] + k to the count
            count += min(freq[arr[i]], freq[arr[i] + k])

    return count
