def first_Missing_Positive(nums, n):
    # Mark negative numbers as visited by making them equal to n+1
    for i in range(n):
        if nums[i] <= 0 or nums[i] > n:
            continue
        index = abs(nums[i]) - 1
        if nums[index] < 0:
            continue
        nums[index] *= -1

    # Find the first positive number's index
