    count_dict = {}
    for tup in lst:
        if tup[0] in count_dict:
            count_dict[tup[0]].append(tup)
        else:
            count_dict[tup[0]] = [tup]

    # Sort the list based on the count of each tuple's first element
    sorted_lst = []
    for key, value in sorted(count_dict.items()):
