def count_Primes_nums(n):
    if n <= 1:
        return 0
    primes = [True] * (n+1)
    p = 2
    while (p * p <= n):
        if primes[p]:
            for i in range(p * p, n+1, p):
                primes[i] = False
        p += 1
    return sum(primes[2:])
```

